                }
            }
            catch (Exception ex)
            {
                nlog.Error(ex, $"[SIGNAL:STEP-2:ERROR] Exception in {GetType().Name} for MsgId:{xdo.MsgId}");
            }
        }

        /// <summary>
        /// 수신된 메시지로부터 시그널 리스트를 추출하는 핵심 메서드
        /// </summary>
        protected internal abstract List<XSignal> Interpret(XDataObject xdo);

        /// <summary>
        /// 기본 시그널 객체 생성 (공통 속성 미리 설정)
