using NLog;
using XTA.Interfaces;
using XTA.Models;
using XTA.XData.Interfaces;

namespace XTA.Core
{
    /// <summary>
    /// XTA 시스템 전역 컨텍스트 및 표준 DI 컨테이너 래퍼
    /// </summary>
    public class XContext
    {
        private static readonly Logger nlog = LogManager.GetCurrentClassLogger();
        private static readonly Lazy<XContext> _instance = new Lazy<XContext>(() => new XContext());
        public static XContext Instance => _instance.Value;

        private IServiceCollection _services = new ServiceCollection();
        private IServiceProvider? _serviceProvider;

        public XParameter Parameter { get; set; }
        public XConfig Config => Parameter?.Config;

        private XContext() { }

        /// <summary>
        /// 서비스 등록 (Build 전 호출 필요)
        /// </summary>
        public void AddService<TService, TImplementation>() 
            where TService : class 
            where TImplementation : class, TService
        {
            _services.AddSingleton<TService, TImplementation>();
            nlog.Trace($"[Context:DI] Registered Singleton: {typeof(TService).Name} -> {typeof(TImplementation).Name}");
        }

        public void AddService<TService>(TService instance) where TService : class
        {
            _services.AddSingleton<TService>(instance);
            nlog.Trace($"[Context:DI] Registered Instance: {typeof(TService).Name}");
        }

        /// <summary>
        /// 등록된 서비스들을 기반으로 컨테이너 빌드
        /// </summary>
        public void Build()
        {
            _serviceProvider = _services.BuildServiceProvider();
            nlog.Info("[Context:DI] ServiceProvider built successfully.");
        }

        public T GetService<T>() where T : class
        {
            if (_serviceProvider == null)
            {
                nlog.Warn($"[Context:DI] ServiceProvider not built yet. Attempting to resolve {typeof(T).Name} from Parameter.");
                return Parameter?.GetService<T>();
            }

            return _serviceProvider.GetService<T>() ?? Parameter?.GetService<T>();
        }

        public T GetService<T>(Predicate<T> filter) where T : class
        {
            // 필터링이 필요한 경우 (예: 여러 인터프리터 중 하나)는 여전히 Parameter의 로직 활용 또는 별도 구현
            return Parameter?.GetService<T>(filter);
        }

        // --- 헬퍼 속성들 (DI 컨테이너에서 해소) ---
        public ISignalRepository SignalRepo => GetService<ISignalRepository>();
        public IXGatewayService Gateway => GetService<IXGatewayService>();
        public ISoundService Sound => GetService<ISoundService>();
        public IDataService Data => GetService<IDataService>();
        public IXTradePolicyService Policy => GetService<IXTradePolicyService>();
        public IXLiquidationService Liquidation => GetService<IXLiquidationService>();
    }
}

