+                    nlog.Info($"[Gateway:PROCESS] >>> Processing individual signal branch: SID:{s.sid} | Cmd:{s.cmd}");
+
+                    if (s.cmd == XCode.CLOSE)
+                    {
+                        nlog.Info($"[Gateway:CLOSE-PATH] Routing to LiquidationService. SID:{s.sid}");
+                        await ctx.Liquidation.ProcessLiquidationAsync(s, xdo.MsgId);
+                        continue;
+                    }
+
+                    // 큐 캐시 업데이트
+                    var signalXdo = new XDataObject
+                    {
+                        Signal = s,
+                        MsgId = xdo.MsgId,
+                        Text = xdo.Text,
+                        CID = xdo.CID,
+                        CNO = xdo.CNO
