using System;
using System.Threading.Tasks;
using XTA.Models;

namespace XTA.Interfaces
{
    /// <summary>
    /// 텔레그램 메시지와 인터프리터 사이의 관문 역할을 하는 서비스 인터페이스
    /// </summary>
    public interface IXGatewayService
    {
        /// <summary>
        /// 해석된 신호를 게이트웨이로 전송하여 처리 요청 (구 Messenger.SendInterpreted 대체)
        /// </summary>
        Task ProcessInterpretedSignalAsync(XDataObject xdo);

        /// <summary>
        /// 원본 메시지를 게이트웨이로 전송하여 해석 및 처리 요청 (구 MSG_TO_INTERPRET 대체)
        /// </summary>
        void EnqueueRawMessage(XDataObject xdo);

        /// <summary>
        /// 신호가 추가되거나 업데이트되었을 때 발생하는 이벤트
        /// </summary>
        event Action<XDataObject>? SignalAddedOrUpdated;

        /// <summary>
        /// 신호가 제거되었을 때 발생하는 이벤트
        /// </summary>
        event Action<string>? SignalRemoved;

        /// <summary>
        /// 로그 메시지 전송 (구 messenger.SendLog 대체)
        /// </summary>
        void Log(string message);
    }
}

