using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using NLog;
using XTA.Core;
using XTA.Interfaces;
using XTA.Models;
using XTA.XData.Models;
using XTA.Validation;
using FluentValidation.Results;

namespace XTA.Services
{
    /// <summary>
    /// 신호의 생명주기 관리, 식별자(SID/GID) 생성 및 최종 검증을 담당하는 서비스
    /// </summary>
    public class XSignalService : IXSignalService
    {
        private static readonly Logger nlog = LogManager.GetCurrentClassLogger();
        private readonly XSignalValidator _validator = new();

        /// <summary>
        /// 해석된 기본 신호를 채널 설정에 맞게 확장(Enrich)하고 검증합니다.
        /// </summary>
        public async Task<List<Models.XSignal>> PrepareSignalsAsync(XDataObject xdo)
        {
            var ctx = XContext.Instance;

            // 1. 정책 적용 (Lot, TP/SL, Grid 등 도메인 로직 실행)
            var enrichedSignals = await ctx.Policy.ApplyPolicyAsync(xdo);
            if (enrichedSignals == null || enrichedSignals.Count == 0) return new List<Models.XSignal>();

            var finalSignals = new List<Models.XSignal>();

            foreach (var s in enrichedSignals)
            {
                try
                {
                    // 2. 식별자 자동 생성 (SID, GID)
                    if (string.IsNullOrEmpty(s.sid))
                    {
                        s.sid = XIdManager.Instance.GenerateSid(s.cno, DateTime.Now, s.sno, s.gno, s.dir, s.type);
                    }
                    if (string.IsNullOrEmpty(s.gid))
                    {
                        s.gid = XIdManager.Instance.GenerateGid(s.cno, DateTime.Now, s.sno);
                    }

                    // 3. 메타데이터 설정
                    s.updated = DateTime.Now;
                    if (s.xe_status == 0) s.SetXeStatus((int)XCode.EaStatus.Ready);

                    // 4. 최종 검증 (Validator 호출)
                    var valResult = _validator.Validate(s);
                    if (valResult.IsValid)
                    {
                        finalSignals.Add(s);
                    }
                    else
                    {
                        string errors = string.Join(", ", valResult.Errors.Select(e => e.ErrorMessage));
                        nlog.Warn($"[Signal:VALIDATE-FAIL] SID:{s.sid} | Errors: {errors}");
                        s.comment = errors; // 에러 사유 기록
                    }
                }
                catch (Exception ex)
                {
                    nlog.Error(ex, $"[Signal:PREPARE-ERROR] Error preparing signal for CNO:{s.cno}");
                }
            }

            return finalSignals;
        }

        public ValidationResult Validate(Models.XSignal signal) => _validator.Validate(signal);
    }
}

