using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Linq;
using ATSA.UI.Models;
using XTA.Models;

namespace ATSA.UI.UCtrls
{
    public class UCXSignalViewModel
    {
        public string ChannelName { get; set; }
        public ObservableCollection<BindableXSignal> Signals { get; } = new ObservableCollection<BindableXSignal>();

        public UCXSignalViewModel(string channelName)
        {
            ChannelName = channelName;
        }

        public void UpdateSignal(BindableXSignal newSignal)
        {
            var existing = Signals.FirstOrDefault(s => s.sid == newSignal.sid);
            if (existing != null)
            {
                // 기존 신호 업데이트
                int index = Signals.IndexOf(existing);
                Signals[index] = newSignal;
            }
            else
            {
                // 새 신호 상단 추가
                Signals.Insert(0, newSignal);
                if (Signals.Count > 50) Signals.RemoveAt(Signals.Count - 1);
            }
        }

        public void AddMockSignal(string sid, int dir, double lot, double price)
        {
            var mock = new BindableXSignal { 
                sid = sid, 
                symbol = "GOLD", 
                dir = dir, 
                lot = lot, 
                price_signal = price, 
                updated = DateTime.Now 
            };
            UpdateSignal(mock);
        }
    }

    public class UCXSignalViewModelDesign
    {
        public string ChannelName { get; } = "CNO-1001 (Design-Time)";
        public ObservableCollection<BindableXSignal> Signals { get; }

        public UCXSignalViewModelDesign()
        {
            Signals = new ObservableCollection<BindableXSignal>
            {
                new BindableXSignal { sid = "20260514-1001-001", symbol = "GOLD", dir = 1, lot = 0.1, price_signal = 2345.50, updated = DateTime.Now },
                new BindableXSignal { sid = "20260514-1001-002", symbol = "EURUSD", dir = 2, lot = 0.5, price_signal = 1.0850, updated = DateTime.Now.AddMinutes(-5) }
            };
        }
    }
}

