            nlog.Trace($"[Context] Service registered: {typeof(T).Name}");
        }

        public T GetService<T>() where T : class
        {
            if (_services.TryGetValue(typeof(T), out var service))
                return (T)service;

            nlog.Warn($"[Context] Service not found: {typeof(T).Name}");
            return null;
        }

