            await Task.CompletedTask;
        }

        private async Task ProcessInterpretedQueueAsync(CancellationToken ct)
        {
            while (await _interpretedChannel.Reader.WaitToReadAsync(ct)) {
                while (_interpretedChannel.Reader.TryRead(out var xdo)) {
                    try {
                        _currentInterpretedXdo = xdo;
                        _procSeq.SetState("Enrich");
                        int safety = 0; while (!_procSeq.IsInState("Idle") && safety++ < 3) await _procSeq.RunAsync();
                    } catch (Exception ex) { nlog.Error(ex, $"[Gateway:PROC] Error: MsgId={xdo?.MsgId}"); }
                }
            }
        }

