using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Linq;
using System.Windows.Input;
using ATSA.UI.UCtrls;
using ATSA.UI.UCtrls.TGMsg;
using ATSA.UI.Models;
using DevExpress.Mvvm;
using XTA.Models;
using XTA.Core;
using XTA.Services.TelegramService;
using XTA.Interfaces;

namespace ATSA.UI.Dashboard
{
    public class DashboardViewModel : ViewModelBase
    {
        public UCXSignalViewModel Channel1001 { get; } = new UCXSignalViewModel("CNO 1001");
        public UCXSignalViewModel Channel1002 { get; } = new UCXSignalViewModel("CNO 1002");
        public UCXSignalViewModel Channel3001 { get; } = new UCXSignalViewModel("CNO 3001");
        public UCXSignalViewModel Channel3002 { get; } = new UCXSignalViewModel("CNO 3002");

        public ObservableCollection<TGMsgItem> RawMessages1001 { get; } = new();
        public ObservableCollection<TGMsgItem> RawMessages1002 { get; } = new();
        public ObservableCollection<TGMsgItem> RawMessages3001 { get; } = new();
        public ObservableCollection<TGMsgItem> RawMessages3002 { get; } = new();

        public int RefreshInterval { get; set; } = 1;

        public ICommand ToggleRefreshCommand { get; }
        public ICommand SampleCommand { get; }

        private readonly Dictionary<int, ObservableCollection<TGMsgItem>> _msgLogByCno;
        private readonly Dictionary<int, UCXSignalViewModel> _signalChannels;

        public DashboardViewModel()
        {
            ToggleRefreshCommand = new DelegateCommand(GenerateMockData);
            SampleCommand = new DelegateCommand(GenerateSampleData);

            _msgLogByCno = new Dictionary<int, ObservableCollection<TGMsgItem>>
            {
                { 1001, RawMessages1001 }, { 1002, RawMessages1002 },
                { 3001, RawMessages3001 }, { 3002, RawMessages3002 }
            };

            _signalChannels = new Dictionary<int, UCXSignalViewModel>
            {
                { 1001, Channel1001 }, { 1002, Channel1002 },
                { 3001, Channel3001 }, { 3002, Channel3002 }
            };

            // 엔진 이벤트 구독
            SubscribeToEngineEvents();
        }

        private void SubscribeToEngineEvents()
        {
            var ctx = XContext.Instance;

            // 1. 텔레그램 메시지 실시간 수신 이벤트 (XTelegram)
            var tg = ctx.GetService<XTelegram>();
            if (tg != null)
            {
                tg.MessageReceived += xdo => OnTelegramMessageReceived(xdo);
                System.Diagnostics.Debug.WriteLine("[Dashboard] Subscribed to XTelegram.MessageReceived");
            }

            // 2. 신호 주입/업데이트 이벤트 (XGatewayService)
            if (ctx.Gateway != null)
            {
                ctx.Gateway.SignalAddedOrUpdated += xdo => OnSignalUpdated(xdo);
                System.Diagnostics.Debug.WriteLine("[Dashboard] Subscribed to XGateway.SignalAddedOrUpdated");
            }
        }

        private void OnTelegramMessageReceived(XDataObject xdo)
        {
            if (xdo == null || !_msgLogByCno.ContainsKey(xdo.CNO)) return;

            System.Windows.Application.Current?.Dispatcher.Invoke(() =>
            {
                var msgLog = _msgLogByCno[xdo.CNO];
                msgLog.Insert(0, new TGMsgItem { 
                    Timestamp = DateTime.Now, 
                    Message = $"[{xdo.CName}] {xdo.Text}" 
                });
                if (msgLog.Count > 500) msgLog.RemoveAt(msgLog.Count - 1);
            });
        }

        private void OnSignalUpdated(XDataObject xdo)
        {
            if (xdo?.Signal == null || !_signalChannels.ContainsKey(xdo.CNO)) return;

            System.Windows.Application.Current?.Dispatcher.Invoke(() =>
            {
                var channel = _signalChannels[xdo.CNO];
                // XTA의 순수 모델을 UI용 Bindable 모델로 변환하여 처리
                var bindable = BindableXSignal.FromModel(xdo.Signal);
                channel.UpdateSignal(bindable);
            });
        }

        private void GenerateSampleData()
        {
            foreach (var ch in _signalChannels.Values)
            {
                ch.Signals.Clear();
                for (int i = 1; i <= 20; i++)
                    ch.AddMockSignal($"{ch.ChannelName.Replace(" ", "-")}-S{i}", i % 2 + 1, 0.1 * i, 2300 + i * 10);
            }
        }

        protected void GenerateMockData()
        {
            foreach (var ch in _signalChannels.Values)
            {
                ch.Signals.Clear();
                for (int i = 1; i <= 3; i++)
                    ch.AddMockSignal($"{ch.ChannelName.Replace(" ", "-")}-{i}", i % 2 + 1, 0.1 * i, 2300 + i * 10);
            }
        }
    }

    public class DashboardViewModelDesign : DashboardViewModel
    {
        public DashboardViewModelDesign() { GenerateMockData(); }
    }
}

