using System;
using System.Collections.ObjectModel;
using System.Windows.Input;
using ATSA.UI.UCtrls;
using ATSA.UI.UCtrls.TGMsg;
using DevExpress.Mvvm;
using XTA.Models;

namespace ATSA.UI.Dashboard
{
    public class DashboardViewModel : ViewModelBase
    {
        public UCXSignalViewModel Channel1001 { get; } = new UCXSignalViewModel("CNO 1001");
        public UCXSignalViewModel Channel1002 { get; } = new UCXSignalViewModel("CNO 1002");
        public UCXSignalViewModel Channel3001 { get; } = new UCXSignalViewModel("CNO 3001");
        public UCXSignalViewModel Channel3002 { get; } = new UCXSignalViewModel("CNO 3002");

        public ObservableCollection<TGMsgItem> RawMessages1001 { get; } = new();
        public ObservableCollection<TGMsgItem> RawMessages1002 { get; } = new();
        public ObservableCollection<TGMsgItem> RawMessages3001 { get; } = new();
        public ObservableCollection<TGMsgItem> RawMessages3002 { get; } = new();

        public int RefreshInterval { get; set; } = 1;

        public ICommand ToggleRefreshCommand { get; }
        public ICommand SampleCommand { get; }

        // CNO별 메시지 로그 컬렉션 매핑
        private Dictionary<int, ObservableCollection<TGMsgItem>> _msgLogByCno;

        public DashboardViewModel()
        {
            ToggleRefreshCommand = new DelegateCommand(GenerateMockData);
            SampleCommand = new DelegateCommand(GenerateSampleData);

            // CNO와 메시지 로그 매핑
            _msgLogByCno = new Dictionary<int, ObservableCollection<TGMsgItem>>
            {
                { 1001, RawMessages1001 },
                { 1002, RawMessages1002 },
                { 3001, RawMessages3001 },
                { 3002, RawMessages3002 }
            };

            // XTA 텔레그램 메시지 수신 핸들러 등록
            System.Diagnostics.Debug.WriteLine($"[DashboardViewModel:CTOR] Initializing Dashboard ViewModel");
            RegisterTelegramMessageHandlers();
        }

        private void RegisterTelegramMessageHandlers()
        {
            var param = App.Param;
            System.Diagnostics.Debug.WriteLine($"[Dashboard:TG_HANDLER] App.Param status: {(param == null ? "NULL" : "INITIALIZED")}");

            if (param == null)
            {
                System.Diagnostics.Debug.WriteLine($"[Dashboard:TG_HANDLER] WARNING: App.Param is null. TG message handlers NOT registered!");
                return;
            }

            System.Diagnostics.Debug.WriteLine($"[Dashboard:TG_HANDLER] Registering handlers for CNOs: {string.Join(", ", _msgLogByCno.Keys)}");

            // 각 CNO별로 메시지 핸들러 등록
            foreach (var cno in _msgLogByCno.Keys)
            {
                var localCno = cno; // 클로저 캡처용
                string channelName = $"TG_MSG_LOG_CNO{cno}";

                try
                {
                    param.messenger.Register<XDataObject>(this, channelName, true, xdo =>
                    {
                        System.Diagnostics.Debug.WriteLine($"[Dashboard:TG_HANDLER] Received message on channel {channelName}: {xdo?.Text?.Substring(0, Math.Min(50, xdo.Text.Length))}");
                        OnTelegramMessageReceived(xdo, localCno);
                    });

                    System.Diagnostics.Debug.WriteLine($"[Dashboard:TG_HANDLER] Successfully registered handler for {channelName}");
                }
                catch (Exception ex)
                {
                    System.Diagnostics.Debug.WriteLine($"[Dashboard:TG_HANDLER] ERROR registering handler for {channelName}: {ex.Message}");
                }
            }

            System.Diagnostics.Debug.WriteLine($"[Dashboard:TG_HANDLER] All handlers registered successfully");
        }

        private void OnTelegramMessageReceived(XDataObject xdo, int cno)
        {
            System.Diagnostics.Debug.WriteLine($"[Dashboard:ON_MSG_RECV] Processing message for CNO {cno}: {xdo?.CName}");

            if (xdo == null)
            {
                System.Diagnostics.Debug.WriteLine($"[Dashboard:ON_MSG_RECV] ERROR: XDataObject is null");
                return;
            }

            if (!_msgLogByCno.ContainsKey(cno))
            {
                System.Diagnostics.Debug.WriteLine($"[Dashboard:ON_MSG_RECV] ERROR: CNO {cno} not found in message log mapping");
                return;
            }

            var msgLog = _msgLogByCno[cno];

            // 메시지 생성
            var tgMsg = new TGMsgItem
            {
                Timestamp = DateTime.Now,
                Message = $"[{xdo.CName}] {xdo.Text}"
            };

            System.Diagnostics.Debug.WriteLine($"[Dashboard:ON_MSG_RECV] Adding message to CNO {cno} log. Current count: {msgLog.Count}");

            // UI 스레드에서 실행되도록 보장
            System.Windows.Application.Current?.Dispatcher.Invoke(() =>
            {
                try
                {
                    // 메시지 로그에 추가 (최대 500개 유지)
                    msgLog.Insert(0, tgMsg);
                    System.Diagnostics.Debug.WriteLine($"[Dashboard:ON_MSG_RECV] Message added successfully. New count: {msgLog.Count}");

                    if (msgLog.Count > 500)
                    {
                        msgLog.RemoveAt(msgLog.Count - 1);
                        System.Diagnostics.Debug.WriteLine($"[Dashboard:ON_MSG_RECV] Removed old message. Count: {msgLog.Count}");
                    }
                }
                catch (Exception ex)
                {
                    System.Diagnostics.Debug.WriteLine($"[Dashboard:ON_MSG_RECV] ERROR adding message to UI: {ex.Message}");
                }
            });
        }

        private void GenerateSampleData()
        {
            foreach (var ch in new[] { Channel1001, Channel1002, Channel3001, Channel3002 })
            {
                ch.Signals.Clear();
                for (int i = 1; i <= 20; i++)
                    ch.AddMockSignal($"{ch.ChannelName.Replace(" ", "-")}-S{i}", i % 2 + 1, 0.1 * i, 2300 + i * 10);
            }

            var logs = new[] { RawMessages1001, RawMessages1002, RawMessages3001, RawMessages3002 };
            foreach (var logList in logs)
            {
                logList.Clear();
                for (int i = 1; i <= 20; i++)
                    logList.Add(new TGMsgItem { Timestamp = DateTime.Now, Message = $"Sample TG Message {i} with long text wrapping test to ensure multi-line display works correctly in the UCXTGMsgView." });
            }
        }

        protected void GenerateMockData()
        {
            foreach (var ch in new[] { Channel1001, Channel1002, Channel3001, Channel3002 })
            {
                ch.Signals.Clear();
                for (int i = 1; i <= 3; i++)
                    ch.AddMockSignal($"{ch.ChannelName.Replace(" ", "-")}-{i}", i % 2 + 1, 0.1 * i, 2300 + i * 10);
            }

            var logs = new[] { RawMessages1001, RawMessages1002, RawMessages3001, RawMessages3002 };
            foreach (var logList in logs)
            {
                logList.Clear();
                for (int i = 1; i <= 5; i++)
                    logList.Add(new TGMsgItem { Timestamp = DateTime.Now, Message = $"Raw TG Message {i}" });
            }
        }
    }

    public class DashboardViewModelDesign : DashboardViewModel
    {
        public DashboardViewModelDesign()
        {
            GenerateMockData();
        }
    }
}

