using System;
using System.Threading.Tasks;
using NLog;
using FluentSeq;
using XTA.Core;
using XTA.Infrastructure.Data;
using XTA.Services;
using XTA.Services.TelegramService;
using XTA.Infrastructure.Audio;
using XTA.XData.Interfaces;
using XTA.Interfaces;

namespace XTA
{
    /// <summary>
    /// 고도화된 XTA 스타트업 엔진 (Stage 3: Standard DI)
    /// </summary>
    public class XTAStartupV2
    {
        private static readonly Logger nlog = LogManager.GetCurrentClassLogger();

        public static async Task RunAsync()
        {
            var ctx = XContext.Instance;

            var sequence = FluentSequence.Create("XTA_STARTUP_V2")
                .Step("LoadConfig", () => {
                    ctx.Parameter = XTAStartup.Initialize();
                    return true;
                })
                .Step("RegisterDataServices", () => {
                    var db = new XpoSqliteService(ctx.Parameter);
                    ctx.AddService<XpoSqliteService>(db);
                    ctx.AddService<ISignalRepository>(db);
                    ctx.AddService<IDataService>(new XDataService(ctx.Parameter));
                    return true;
                })
                .Step("RegisterDomainServices", () => {
                    ctx.AddService<IXTradePolicyService, XTradePolicyService>();
                    ctx.AddService<IXLiquidationService, XLiquidationService>();
                    ctx.AddService<IXSignalService, XSignalService>();
                    ctx.AddService<IXGatewayService>(new XGatewayService(ctx.Parameter));
                    return true;
                })
                .Step("RegisterInfraServices", () => {
                    ctx.AddService<ISoundService>(new XSoundService(ctx.Parameter));
                    ctx.AddService<ITtsService>(new XTtsService(ctx.Parameter));
                    ctx.AddService(new XSyncWorker(ctx.Parameter));
                    ctx.AddService(new XTelegram(ctx.Parameter));
                    return true;
                })
                .Step("BuildContainer", () => {
                    // Stage 3 핵심: 서비스 컨테이너 빌드
                    ctx.Build();
                    return true;
                })
                .Step("StartServices", () => {
                    // 등록된 모든 서비스(XObject 계열) 일제 시작
                    XTAStartup.Start(ctx.Parameter);
                    return true;
                })
                .OnFailure(err => {
                    nlog.Fatal($"[Startup:FATAL] Failed at {err.StateName}: {err.Exception?.Message}");
                })
                .Build();

            await sequence.StartAsync();
        }

        public static async Task ProcessTransferAsync()
        {
            var ctx = XContext.Instance;
            
            var transferSeq = FluentSequence.Create("DATA_TRANSFER")
                .Step("ScanClosedSignals", async () => {
                    var repo = ctx.SignalRepo;
                    if (repo == null) return false;
                    var closedSignals = await repo.GetClosedSignalsAsync();
                    return closedSignals.Count > 0;
                })
                .Step("ExecuteTransfer", async () => {
                    var dataSvc = ctx.Data;
                    if (dataSvc == null) return false;
                    
                    nlog.Info("[Transfer] Moving closed signals to history...");
                    await dataSvc.ArchiveSignalsAsync();
                    return true;
                })
                .OnSuccess(() => nlog.Info("[Transfer] Data migration completed successfully."))
                .Build();

            await transferSeq.StartAsync();
        }
    }
}

